// BDP = bandwidth (bytes/s) * RTT (s)
const mbps = 20;
const rttMs = 150;
const bytesPerSec = (mbps * 1e6) / 8;
const bdpBytes = bytesPerSec * (rttMs / 1000);
console.log('BDP =', Math.round(bdpBytes), 'bytes =', (bdpBytes / 1024).toFixed(1), 'KiB');
console.log('A window smaller than the BDP cannot fill the pipe.');
